            mx    %00

palCurrent  dw    0                   ; PAL_* id of the palette on screen (0 = none yet)

; SetDefaultPalette
;
; Before the game uploads a palette: the swizzle tables are title's, but no palette is current until one
; is detected ("start = none" in the transitions file), so no colors are loaded in the meantime.
; Called by the game's InitPlayfield (NES_StartUp) and at start-up.
SetDefaultPalette
            ldy   #PAL_TITLE
            ldx   PAL_SWIZZLE_LO,y
            lda   PAL_SWIZZLE_HI,y
            jmp   NES_SetPaletteMap

; ApplyPaletteChange
;
; The game's PRE_RENDER hook (jsl), on the GS task.  If the palette RAM changed (ppuPalDirty, set by the
; engine's palette write handler), identify the palette in it and switch to it, or show its changed
; colors in the current palette's layout (fades, color cycling, an unknown palette).  While the
; background is off, the game is rebuilding the screen: the old colors stay on whatever is left on it,
; and the new ones come with the new screen.
ApplyPaletteChange
            ldal  ppuPalDirty
            beq   :none
            ldal  _ppumask
            and   #NES_PPUMASK_BG
            beq   :none
            lda   #0
            stal  ppuPalDirty         ; (first, so a write from here on is seen next time)
            ldx   palCurrent
            jsr   DetectNESPalette    ; A = Y = palette id, 0 if none
            beq   :colors             ; not a known palette (e.g. a step of a fade)
            cmp   palCurrent
            beq   :colors
            ldx   palCurrent
            sty   palCurrent
            jsr   UpdatePalette       ; X = from, Y = to
            rtl
:colors     ldy   palCurrent
            beq   :none               ; no palette yet
            jsr   LoadPaletteColors
:none       rtl

; PalSetWrites
;
; Y = palette id (kept).  The palette RAM writes that go straight to their IIgs slot while it is on
; screen (its [direct] cells); the rest mark the palette dirty.  The palettes with the same [direct]
; slots share a table, and it is only installed when it changes.
PalSetWrites
            lda   PAL_WRITES,y
            cmp   palWrites
            beq   :same
            sta   palWrites
            phy
            ldx   #^PAL_WRITES
            jsl   PPU_SetPaletteWritesL
            ply
:same       rts

palWrites   dw    PAL_WRITES_NONE     ; The table installed (the engine's starts with every write marking dirty)

; UpdatePalette
;
; X = from palette id (PAL_*, or 0 for none), Y = to palette id
;
; Switches the swizzle tables to the new palette, loads its colors (LoadPaletteColors), then redraws
; the background groups whose slots changed.  Call from the GS task (it redraws tiles).
UpdatePalette
            lda   BG_UPDATE_MASKS,x
            pha
            lda   (1,s),y
            sta   1,s                 ; 1,s = groups to redraw

            phy
            ldx   PAL_SWIZZLE_LO,y
            lda   PAL_SWIZZLE_HI,y
            jsr   NES_SetPaletteMap
            ply
            jsr   PalSetWrites        ; Y = palette id

            jsr   LoadPaletteColors
            pla
            jsl   RefreshPPUAttributesL   ; (in the engine bank: ppu_entry.s)
            rts

; LoadPaletteColors
;
; Y = palette id.  Loads IIgs palette 0 from the current NES palette RAM, in the palette's layout,
; so the colors the game changes on the fly (fades, color cycling, ...) are shown too.  Slot 0 (the
; universal background color) is left alone: the game's $3F00 writes set it directly.
LoadPaletteColors
            lda   PAL_CELLS,y
            pha                       ; 1,s = slot map
            ldy   #31                 ; Backwards, so the BG colors win a shared slot
:loop       lda   (1,s),y
            and   #$00FF
            cmp   #$00FF
            beq   :next               ; not shown
            pha                       ; 1,s = slot * 2
            tyx
            ldal  PPU_MEM+$3F00,x
            jsr   NES_ColorToIIgs_X
            plx
            stal  SHR_PALETTES,x
:next       dey
            bpl   :loop
            pla
            rts

; DetectNESPalette
;
; X = the current palette id (0 = none).  Returns A = Y = the PAL_* id of the palette whose
; colors 1-3 are all in palette RAM (other than the reserved ones), or 0 if there is none (e.g. a
; step of a fade).  The current palette is tried first,
; then the palettes that follow it in the transitions, then the rest.
DetectNESPalette
            php
            rep   #$30
            stx   :from
            txa
            beq   :all
            jsr   :match              ; still the current palette?
            bcs   :found
            ldx   :from
            lda   PAL_SUCC,x          ; its successors, a 0-terminated list of ids
:snext      sta   :ptr
            tax
            lda:  0,x
            beq   :all
            tax
            jsr   :match
            bcs   :found
            lda   :ptr
            inc
            inc
            bra   :snext
:all        ldx   #2
:anext      jsr   :match
            bcs   :found
            inx
            inx
            cpx   #24
            bcc   :anext
            ldx   #0
:found      txy
            plp
            tya
            rts

; X = palette id.  Carry set if its colors are in palette RAM.  X is kept.  Only colors 1-3 of
; each group are compared (24 at most): color 0 is always IIgs slot 0.  One pass per group, from
; SP3 back to BG0, with its three colors compared inline.  NES colors are $00-$3F, so the $FF of a
; reserved or unused color is the only table byte with bit 7 set, and bmi skips it.
:match      phx
            lda   PAL_MATCH,x
            clc
            adc   #21
            tay                       ; Y -> the last group's 3 bytes
            ldx   #28                 ; X = the last group's palette RAM offset
            sep   #$20
            mx    %10
:group      lda:  0,y                 ; color 1
            bmi   *+8                 ; $FF = any value
            cmpl  PPU_MEM+$3F01,x
            bne   :mfail
            lda:  1,y                 ; color 2
            bmi   *+8
            cmpl  PPU_MEM+$3F02,x
            bne   :mfail
            lda:  2,y                 ; color 3
            bmi   *+8
            cmpl  PPU_MEM+$3F03,x
            bne   :mfail
            dey
            dey
            dey
            dex
            dex
            dex
            dex
            bpl   :group
            rep   #$20
            mx    %00
            plx
            sec
            rts
:mfail      rep   #$20
            plx
            clc
            rts

:from       ds    2
:ptr        ds    2

; id -> colors 1-3 of each group to match (BG0-BG3, SP0-SP3; $FF = any value: reserved or unused)
PAL_MATCH
            dw    0
            dw    PAL_TITLE_MATCH
            dw    PAL_TITLE_2_MATCH
            dw    PAL_LEVEL_1_MATCH
            dw    PAL_LEVEL_2_MATCH
            dw    PAL_LEVEL_3_MATCH
            dw    PAL_LEVEL_4_MATCH
            dw    PAL_LEVEL_5_MATCH
            dw    PAL_LEVEL_6_MATCH
            dw    PAL_LEVEL_7_MATCH
            dw    PAL_LEVEL_8_MATCH
            dw    PAL_ENDING_MATCH
PAL_TITLE_MATCH
            db    $10,$28,$16,$30,$10,$15,$10,$28,$38,$0F,$0F,$0F   ; BG0-BG3
            db    $30,$10,$00,$30,$38,$28,$2C,$1C,$0C,$00,$00,$00   ; SP0-SP3
PAL_TITLE_2_MATCH
            db    $10,$28,$16,$30,$10,$15,$10,$28,$38,$30,$36,$26   ; BG0-BG3
            db    $30,$10,$00,$30,$38,$28,$2C,$1C,$0C,$00,$00,$00   ; SP0-SP3
PAL_LEVEL_1_MATCH
            db    $19,$29,$08,$28,$18,$08,$FF,$30,$10,$FF,$FF,$FF   ; BG0-BG3
            db    $37,$12,$0F,$36,$16,$0F,$20,$26,$16,$20,$00,$0F   ; SP0-SP3
PAL_LEVEL_2_MATCH
            db    $10,$00,$09,$00,$0C,$20,$FF,$30,$10,$FF,$FF,$FF   ; BG0-BG3
            db    $37,$12,$0F,$36,$16,$0F,$20,$26,$16,$20,$1B,$0F   ; SP0-SP3
PAL_LEVEL_3_MATCH
            db    $0A,$1A,$00,$28,$18,$07,$FF,$30,$10,$FF,$FF,$FF   ; BG0-BG3
            db    $37,$12,$0F,$36,$16,$0F,$20,$26,$16,$20,$00,$0F   ; SP0-SP3
PAL_LEVEL_4_MATCH
            db    $10,$00,$0C,$00,$06,$20,$16,$30,$10,$38,$09,$06   ; BG0-BG3
            db    $37,$12,$0F,$36,$16,$0F,$20,$26,$16,$20,$1B,$0F   ; SP0-SP3
PAL_LEVEL_5_MATCH
            db    $20,$10,$1C,$20,$10,$0A,$16,$30,$10,$20,$22,$02   ; BG0-BG3
            db    $37,$12,$0F,$36,$16,$0F,$20,$26,$16,$20,$00,$0F   ; SP0-SP3
PAL_LEVEL_6_MATCH
            db    $00,$20,$1A,$01,$20,$00,$16,$30,$10,$20,$27,$17   ; BG0-BG3
            db    $37,$12,$0F,$36,$16,$0F,$20,$26,$16,$20,$00,$0F   ; SP0-SP3
PAL_LEVEL_7_MATCH
            db    $27,$17,$06,$20,$10,$00,$16,$30,$10,$06,$1B,$0B   ; BG0-BG3
            db    $37,$12,$0F,$36,$16,$0F,$20,$26,$16,$20,$00,$0F   ; SP0-SP3
PAL_LEVEL_8_MATCH
            db    $10,$00,$07,$36,$15,$06,$35,$15,$04,$18,$13,$03   ; BG0-BG3
            db    $37,$12,$0F,$36,$16,$0F,$30,$28,$16,$30,$25,$14   ; SP0-SP3
PAL_ENDING_MATCH
            db    $30,$10,$00,$18,$07,$1A,$16,$18,$07,$20,$10,$11   ; BG0-BG3
            db    $0B,$1B,$3B,$16,$00,$00,$20,$26,$16,$20,$10,$00   ; SP0-SP3

; id -> the ids of the palettes that can follow it (transitions), 0-terminated
PAL_SUCC
            dw    PAL_NONE_SUCC
            dw    PAL_TITLE_SUCC
            dw    PAL_TITLE_2_SUCC
            dw    PAL_LEVEL_1_SUCC
            dw    PAL_LEVEL_2_SUCC
            dw    PAL_LEVEL_3_SUCC
            dw    PAL_LEVEL_4_SUCC
            dw    PAL_LEVEL_5_SUCC
            dw    PAL_LEVEL_6_SUCC
            dw    PAL_LEVEL_7_SUCC
            dw    PAL_LEVEL_8_SUCC
            dw    PAL_ENDING_SUCC
PAL_NONE_SUCC
            dw    0
PAL_TITLE_SUCC
            dw    PAL_TITLE_2,PAL_LEVEL_1,PAL_LEVEL_2,PAL_LEVEL_3,PAL_LEVEL_4,PAL_LEVEL_5,PAL_LEVEL_6,PAL_LEVEL_7,PAL_LEVEL_8,0
PAL_TITLE_2_SUCC
            dw    PAL_TITLE,PAL_LEVEL_1,PAL_LEVEL_2,PAL_LEVEL_3,0
PAL_LEVEL_1_SUCC
            dw    PAL_TITLE,PAL_LEVEL_2,0
PAL_LEVEL_2_SUCC
            dw    PAL_TITLE,PAL_LEVEL_3,PAL_LEVEL_1,0
PAL_LEVEL_3_SUCC
            dw    PAL_TITLE,PAL_LEVEL_4,PAL_LEVEL_1,0
PAL_LEVEL_4_SUCC
            dw    PAL_TITLE,PAL_LEVEL_5,PAL_LEVEL_1,0
PAL_LEVEL_5_SUCC
            dw    PAL_TITLE,PAL_LEVEL_6,PAL_LEVEL_1,0
PAL_LEVEL_6_SUCC
            dw    PAL_TITLE,PAL_LEVEL_7,PAL_LEVEL_1,0
PAL_LEVEL_7_SUCC
            dw    PAL_TITLE,PAL_LEVEL_8,PAL_LEVEL_1,0
PAL_LEVEL_8_SUCC
            dw    PAL_TITLE,PAL_ENDING,PAL_LEVEL_1,0
PAL_ENDING_SUCC
            dw    PAL_TITLE,PAL_LEVEL_1,0

; id -> swizzle tables (PALDATA segment, palettes.s)
PAL_SWIZZLE_LO
            dw    0
            dw    PAL_TITLE_SWIZZLE
            dw    PAL_TITLE_2_SWIZZLE
            dw    PAL_LEVEL_1_SWIZZLE
            dw    PAL_LEVEL_2_SWIZZLE
            dw    PAL_LEVEL_3_SWIZZLE
            dw    PAL_LEVEL_4_SWIZZLE
            dw    PAL_LEVEL_5_SWIZZLE
            dw    PAL_LEVEL_6_SWIZZLE
            dw    PAL_LEVEL_7_SWIZZLE
            dw    PAL_LEVEL_8_SWIZZLE
            dw    PAL_ENDING_SWIZZLE
PAL_SWIZZLE_HI
            dw    0
            dw    ^PAL_TITLE_SWIZZLE
            dw    ^PAL_TITLE_2_SWIZZLE
            dw    ^PAL_LEVEL_1_SWIZZLE
            dw    ^PAL_LEVEL_2_SWIZZLE
            dw    ^PAL_LEVEL_3_SWIZZLE
            dw    ^PAL_LEVEL_4_SWIZZLE
            dw    ^PAL_LEVEL_5_SWIZZLE
            dw    ^PAL_LEVEL_6_SWIZZLE
            dw    ^PAL_LEVEL_7_SWIZZLE
            dw    ^PAL_LEVEL_8_SWIZZLE
            dw    ^PAL_ENDING_SWIZZLE

; id -> palette RAM writes: for each entry, the IIgs slot * 2 its writes go to straight away while
; the palette is on screen ([direct] cells), or $FFFF: they mark the palette dirty (PPU_SetPaletteWritesL).
; One table per distinct set of [direct] slots.
PAL_WRITES
            dw    0
            dw    PAL_WRITES_NONE   ; title
            dw    PAL_WRITES_NONE   ; title_2
            dw    PAL_WRITES_1   ; level_1
            dw    PAL_WRITES_1   ; level_2
            dw    PAL_WRITES_1   ; level_3
            dw    PAL_WRITES_NONE   ; level_4
            dw    PAL_WRITES_NONE   ; level_5
            dw    PAL_WRITES_NONE   ; level_6
            dw    PAL_WRITES_NONE   ; level_7
            dw    PAL_WRITES_NONE   ; level_8
            dw    PAL_WRITES_NONE   ; ending
PAL_WRITES_NONE   ; title, title_2, level_4, level_5, level_6, level_7, level_8, ending
            dw    $FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF
            dw    $FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF
            dw    $FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF
            dw    $FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF
PAL_WRITES_1   ; level_1, level_2, level_3
            dw    $FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF
            dw    $FFFF,$10,$FFFF,$FFFF,$FFFF,$12,$14,$16
            dw    $FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF
            dw    $FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF,$FFFF

; id -> slot map: for each NES palette RAM entry, the IIgs slot * 2, or $FF if it isn't loaded
; (color 0, which the game writes straight to slot 0, colors that share slot 0 with it, and
; approximated colors, which are shown in another color's slot)
PAL_CELLS
            dw    0
            dw    PAL_TITLE_CELLS
            dw    PAL_TITLE_2_CELLS
            dw    PAL_LEVEL_1_CELLS
            dw    PAL_LEVEL_2_CELLS
            dw    PAL_LEVEL_3_CELLS
            dw    PAL_LEVEL_4_CELLS
            dw    PAL_LEVEL_5_CELLS
            dw    PAL_LEVEL_6_CELLS
            dw    PAL_LEVEL_7_CELLS
            dw    PAL_LEVEL_8_CELLS
            dw    PAL_ENDING_CELLS
PAL_TITLE_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$02,$0A,$FF,$10,$0C,$0E,$FF,$12,$14,$16   ; BG0-BG3
            db    $FF,$08,$02,$18,$FF,$08,$0E,$04,$FF,$1A,$1C,$1E,$FF,$18,$18,$18   ; SP0-SP3
PAL_TITLE_2_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$02,$0A,$FF,$10,$0C,$0E,$FF,$12,$14,$16   ; BG0-BG3
            db    $FF,$08,$02,$18,$FF,$08,$0E,$04,$FF,$1A,$1C,$1E,$FF,$18,$18,$18   ; SP0-SP3
